order by due_time

mapper.update:
update work_tasks
set status = 'CANCELLED', update_by = #{updateBy}, update_time = now()
where house_id = #{houseId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'PENDING'

mapper.sql:
